func (v BotValue) Equal(o attr.Value) bool {
	other, ok := o.(BotValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AgentId.Equal(other.AgentId) {
		return false
	}

	if !v.AllowedChannels.Equal(other.AllowedChannels) {
		return false
	}

	if !v.BotId.Equal(other.BotId) {
		return false
	}

	if !v.Connected.Equal(other.Connected) {
		return false
	}

	if !v.CreatedAt.Equal(other.CreatedAt) {
		return false
	}

	if !v.Keywords.Equal(other.Keywords) {
		return false
	}

	if !v.KeywordsEnabled.Equal(other.KeywordsEnabled) {
		return false
	}

	if !v.SessionTtlDays.Equal(other.SessionTtlDays) {
		return false
	}

	if !v.SetupType.Equal(other.SetupType) {
		return false
	}

	if !v.SlashCommands.Equal(other.SlashCommands) {
		return false
	}

	if !v.Status.Equal(other.Status) {
		return false
	}

	if !v.UpdatedAt.Equal(other.UpdatedAt) {
		return false
	}

	return true
}

